window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-24T02:18:02.597Z","stories":{"68ccf963-6e38-4e86-b2f3-289bd70774fb":{"publicId":"68ccf963-6e38-4e86-b2f3-289bd70774fb","title":"英伟达董事会全票恢复黄仁勋职务","status":"active","sourceCount":11,"reportCount":19,"firstReportAt":"2026-11-13T08:23:04.000Z","latestAt":"2026-11-23T20:46:15.000Z","latest":"NVIDIA 董事会撤销决定，恢复黄仁勋 CEO、总裁兼董事职务","digest":"英伟达董事会11月23日一致投票，即刻恢复黄仁勋的总裁、CEO及董事职务，距其辞职不到两周。董事会称，在咨询美国政府高层后认定黄仁勋回归不构成国家安全风险，并称后续会谈确认了他的坦率；临时CEO Colette Kress继续担任CFO。消息公布后股价盘初大涨约30%至31%。\n\n黄仁勋辞职期间，数百名员工签署内部信要求董事会辞职并恢复其职务，投资人Brad Gerstner和Gavin Baker致信董事会呼吁保留其回归选项，请愿网站显示逾20万人签名。FT曾报道董事会接触Arm CEO Rene Haas作为潜在继任人选；董事长Harvey Jones在复职前不到一周还表示无意让其回归。\n\n针对黄仁勋成为境外情报行动目标的独立董事调查将继续进行，公司另设国家安全与出口管制委员会并招聘首席合规官；The Verge称美国证券交易委员会也在审查英伟达的会计操作。WSJ曾报道，黄仁勋被罢免更多源于公司高风险业务，而非私生活。","digestUpdatedAt":"2026-11-23T21:58:47.558Z","reports":[{"id":"zto0pspydy8330r0bvwqb6j5z","title":"ChinaTalk播客：Nvidia董事会恢复黄仁勋CEO职务，Megaspeed被列入实体清单","summary":"ChinaTalk主持Jordan Schneider邀请Chris McGuire和Peter Harrell录制播客，讨论Nvidia董事会全票恢复黄仁勋CEO职务（距其辞职仅十一天），以及美国商务部同日将Megaspeed列入实体清单。嘉宾围绕出口管制与制裁实务，分析了董事会决策背景、Megaspeed实体清单未附加外国直接产品规则（FDPR）等细节，并探讨了后续监管走向。","sourceName":"ChinaTalk（RSS）","firstParty":false,"publishedAt":"2026-11-24T01:41:25.000Z","url":"https://www.chinatalk.media/p/jensen-returns"},{"id":"hmsq0aeol4xxxs3ksg5e5u12u","title":"NVIDIA 董事会撤销决定，恢复黄仁勋 CEO、总裁兼董事职务","summary":"NVIDIA 董事会一致投票恢复黄仁勋的总裁、CEO 及董事职务，消息公布后股价上涨 31%。此前不到一周董事长 Harvey Jones 还表示不打算让他回归，董事会称后续会谈确认了其坦诚度，美国政府高层保证其回归不构成国家安全风险，特朗普也表态支持。黄仁勋在总部表示第二次机会后会做得更好。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-23T20:46:15.000Z","url":"https://x.com/rohanpaul_ai/status/2124967788905365714"},{"id":"zx2hatsv8edumgbbvqqwxtito","title":"英伟达董事会恢复黄仁勋CEO职务","summary":"英伟达董事会11月24日宣布恢复黄仁勋的CEO、总裁及董事职务。黄仁勋此前于11月12日因个人事务及公司相关调查压力辞职，随后包括美国总统特朗普在内的多方人士对其复职表达支持，白宫方面表示政府向董事会提供了意见。英伟达股价在复职消息公布后上涨，但董事会表示针对黄仁勋的调查仍将继续，美国证券交易委员会也在审查英伟达的会计操作。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T19:57:18.000Z","url":"https://www.theverge.com/tech/1040428/nvidia-jensen-huang-ceo-return"},{"id":"g4u96z1szup8rzfhyotvhk5ef","title":"NVIDIA 董事会恢复黄仁勋职务，股价盘初大涨 30%","summary":"NVIDIA 董事会宣布恢复黄仁勋的 President、CEO 和董事职务。此前从其个人生活相关报道首次出现到上周五收盘，NVIDIA 市值缩水约 1.47 万亿美元，约 33%；公告发布后股价盘初上涨 30%。Trump 在 Truth Social 发文支持该决定，称政府没有理由认为黄仁勋回归构成国家安全风险，司法部长已确认政府没有证据表明黄仁勋有任何违法行为。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-23T15:07:54.000Z","url":"https://x.com/rohanpaul_ai/status/2124882639798849601"},{"id":"jo5418ootux72grn8ugtpiq4k","title":"NVIDIA 董事会全票恢复黄仁勋总裁兼 CEO 及董事职务，股价大涨 31%","summary":"NVIDIA 于 11 月 23 日宣布，董事会全票决定即刻恢复黄仁勋的总裁兼 CEO 和董事职务，股价随后上涨 31%，距董事长 Harvey Jones 表示无意让其回归不到一周。董事会称后续会谈确认了他的坦率，且美国政府高层保证其回归不构成国家安全风险；针对境外情报调查的独立调查委员会将继续推进，黄仁勋表示配合，同时公司新组建国家安全与出口管控委员会，临时 CEO Colette Kress 继续留任 CFO。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-23T14:39:10.000Z","url":"https://x.com/rohanpaul_ai/status/2124875409703719174"},{"id":"qte4xgs14r832tda2qb0kq3op","title":"黄仁勋复职英伟达 CEO，董事会投票恢复其职务","summary":"英伟达董事会于 23 日 21:58 一致投票恢复黄仁勋总裁、CEO 和董事职务，即时生效，理由是其态度坦诚且复职不构成安全风险。此前 11、12 号黄仁勋离职，20 万人签名支持，18 号财报会营收 1158 亿美元、同比增长 103%，董事会一度表示不打算让其复职并寻找永久 CEO；川普公开力挺后局势转折。","sourceName":"公众号：卡尔的AI沃茨","firstParty":false,"publishedAt":"2026-11-23T14:36:44.000Z","url":"https://mp.weixin.qq.com/s/gR_c-k_evwV-Iyg6Z7vFQg"},{"id":"bc4gq9dugsnk7163n4wdgji1j","title":"Nvidia 宣布黄仁勋重返 CEO 职位","summary":"Nvidia 董事会周一宣布重新任命黄仁勋为 CEO 兼总裁，距其因婚外情风波辞职不到两周。董事会称在咨询美国政府高级官员后认定黄仁勋不构成国家安全风险，并一致认为他适合领导公司；股价开盘大涨 30%，美东时间 9:51 报 159.95 美元，涨 27%。Colette Kress 将继续担任 CFO。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T14:21:59.000Z","url":"https://techcrunch.com/2026/11/23/nvidia-reverses-course-and-brings-jensen-huang-back-as-ceo/"},{"id":"gdveoivkyxm7gf8k5tsspii95","title":"NVIDIA 董事会恢复黄仁勋总裁、CEO 兼董事职务","summary":"作者引用 NVIDIA 新闻室公告称，NVIDIA 董事会恢复黄仁勋（Jensen Huang）总裁、CEO 兼董事会董事职务，并附官方公告链接；作者正文只有一句玩梗配图 Return of the Jensen。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-23T14:12:44.000Z","url":"https://x.com/indigox/status/2124868756723863790"},{"id":"ajcxs84uezjqgsgxpdtr31o0l","title":"NVIDIA 宣布黄仁勋复任总裁兼 CEO 并重回董事会","summary":"NVIDIA 于 11 月 23 日宣布黄仁勋即刻复任总裁、CEO 及董事会成员，董事会一致投票通过，临时 CEO Colette Kress 继续担任 CFO。复职决定参考了美国政府高层意见，董事会认为其不构成国家安全风险，此前因黄仁勋成为外国情报行动目标而启动的独立董事调查将继续进行，董事会另设国家安全与出口管制委员会并招聘首席合规官。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-23T14:04:30.000Z","url":"https://x.com/thexpin/status/2124866686025400819"},{"id":"rk143d9qa0j9gp3fdti162fy7","title":"英伟达CEO黄仁勋辞职后风波持续，公司股价一周下跌14%","summary":"英伟达CEO黄仁勋于上周辞任，公司股价随之下跌14%，CFO Colette Kress出任临时CEO。辞职数小时后，路透社报道其第三段婚外情。事件还涉及公司芯片供应相关指控，国会议员已启动调查。报道称黄仁勋正联络盟友寻求回归，业内担心动荡加剧营收压力，可能促使公司在安全投入上有所松懈。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-16T13:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031740/jensen-huang-nvidia-scandal-isnt-slowing-down"},{"id":"wsgiqmx7p9pxizrd178ybun5j","title":"投资者致信 Nvidia 董事会呼吁保留黄仁勋回归 CEO 的选项","summary":"Brad Gerstner 和 Gavin Baker 致信 Nvidia 董事会，敦促其不要急于替换黄仁勋，并将他回归 CEO 的可能性保留在议题中。Rohan Paul 转发了 standwithjensen.com 请愿网站，页面显示已有 109,729 名 Nvidia 员工、59,077 名股东和 43,947 名支持者签名，要求董事会给出答复。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-14T19:38:34.000Z","url":"https://x.com/rohanpaul_ai/status/2121689263163232362"},{"id":"s59xfwl0atld8vs7xq0pdx6hw","title":"WSJ 报道称黄仁勋被罢免更多源于 Nvidia 高风险业务而非私生活","summary":"The Decoder 援引 WSJ 报道分析称，黄仁勋被罢免更多源于 Nvidia 高风险业务而非私生活传闻。Nvidia 在其主导下向 AI 云厂商和数据中心开发商提供数十亿美元财务担保以换取营收分成，最大一笔涉及对 OpenAI 俄亥俄数据中心的 2500 亿美元担保，消息公布后股价跌 5%，临时 CEO Colette Kress 将该承诺减半。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T20:07:34.000Z","url":"https://the-decoder.com/jensen-huangs-ouster-likely-traces-back-to-nvidias-risky-business-practices-more-than-his-personal-life/"},{"id":"p1mfh9oe0xbq4evyru5pp1ikt","title":"Nvidia 危机与 Anthropic IPO 前夜的 Cerebral Valley AI Summit 现场观察","summary":"Newcomer 在旧金山 Cerebral Valley AI Summit 现场报道：Jensen Huang 因第二段婚外情披露辞职，Reuters 当天报道存在第三段，与会者多认为 Nvidia 短期无碍但生态承压，Databricks CEO 称其对整个生态是打击。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-13T19:27:39.000Z","url":"https://www.newcomer.co/p/nvidia-crises-anthropic-ipo-and-off"},{"id":"wk33v2eb2ubx9wca68hhwm901","title":"FT 报道 Nvidia 董事会接触 Arm CEO Rene Haas 考虑接替黄仁勋","summary":"据 FT 报道，Nvidia 董事会接触了 Arm CEO Rene Haas，作为接替黄仁勋的可能人选。Haas 自 2022 年起执掌这家软银旗下的英国芯片设计公司，十多年前曾在 Nvidia 工作约 7 年，与黄仁勋及部分董事保持密切关系，但他只是多位候选人之一，未必会获得或接受这一职位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T17:34:44.000Z","url":"https://x.com/rohanpaul_ai/status/2121295713502199821"},{"id":"wkxqhc700pv5zgpew0cj5zyec","title":"Vergecast 播客解读黄仁勋辞任 NVIDIA CEO 后的连锁影响","summary":"The Vergecast 播客中 David Pierce 与 Nilay 梳理 NVIDIA CEO 黄仁勋周四辞职事件，并讨论后续可能展开的更大故事：NVIDIA 在中国的业务、美国政府的态度，以及整个 AI 行业的稳定性。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T14:47:16.000Z","url":"https://www.theverge.com/podcast/1032866/jensen-huang-nvidia-china-trump-vergecast"},{"id":"pdhda5tufq7ubi8w17bys7w66","title":"Nvidia 领导层变动引发以色列科技界关注，投资人认为挑战者或有机会","summary":"Nvidia 前CEO黄仁勋辞职后，以色列科技界关注这家在其拥有6000名员工和最大海外研发中心的公司是否会继续深耕以色列。多位以色列投资人认为，Nvidia 决策放缓可能给 AI 芯片和推理软件领域的竞争者留出空间，但如果不确定性也拖慢 AI 支出，竞争者面对的可能是更小的市场机会。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T12:52:19.000Z","url":"https://techcrunch.com/2026/11/13/israels-vcs-see-opportunity-for-challengers-in-nvidias-turmoil/"},{"id":"se0y4v3gihr6s0jmrc5vuv1zo","title":"AINews：黄仁勋辞任 NVIDIA CEO，Colette Kress 出任临时 CEO","summary":"Latent Space 的 AI 新闻日报头条是 NVIDIA 宣布黄仁勋在任职 33 年后辞去 CEO、总裁和董事职务，CFO Colette Kress 出任临时 CEO，SEC 文件显示董事会于 11 月 11 日接受辞呈，此前董事会已就 NYT 报道的绯闻事件展开独立调查。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:04:13.000Z","url":"https://latent.space/p/ainews-jensen-huang-resigns-after-33-years-leading-nvidia/"},{"id":"w9235nqq0senjfvm8lz7g51aa","title":"NVIDIA 员工内部信要求董事会辞职并恢复黄仁勋 CEO 职务","summary":"X.PIN 转发消息称，数百名 NVIDIA 员工签署内部公开信，要求董事会辞职并恢复黄仁勋 CEO 职务。信中指控董事会在无具体证据的情况下罢免黄仁勋、诚信谈判，称若董事会不满足要求，员工可能转投 Elon Musk 承诺安排职位的 SpaceX 与 Terafab，并列出 Bill Daly、Ian Buck 等署名员工。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-13T08:23:04.000Z","url":"https://x.com/thexpin/status/2121156882064937448"},{"id":"n73ab4h9gqlu6ucv69ynzxln4","title":"SemiAnalysis 分析黄仁勋辞任 Nvidia 后的公司结构与出口管制走向","summary":"SemiAnalysis 长文分析黄仁勋辞任 Nvidia CEO 后的连锁影响，作者推测其去职与 GPU 走私及美国推动 RASA 出口管制立法有关。文中指出公司约 60 名直管高管的扁平结构依赖黄本人，继任者 Colette Kress 为临时 CEO，Ian Buck 与 Jonah Alben 被视为技术侧人选但无人能全面接替。","sourceName":"SemiAnalysis 长文 RSS（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:06:26.000Z","url":"https://newsletter.semianalysis.com/p/nvidia-and-the-world-without-jensen"}]},"fc5a905b-54af-4de4-9c7c-a366a60a9f84":{"publicId":"fc5a905b-54af-4de4-9c7c-a366a60a9f84","title":"智谱发布GLM-5.4旗舰模型并上线Coding Plan","status":"active","sourceCount":6,"reportCount":6,"firstReportAt":"2026-11-23T04:49:30.313Z","latestAt":"2026-11-23T23:40:49.000Z","latest":"Simon Willison 实测 Z.ai 的 GLM 5.4 及其 Loop Transformer 架构","digest":"智谱发布旗舰模型 GLM-5.4，并已向 GLM Coding Plan 全量用户开放，同步上线 ZCode、Trae、WorkBuddy、Qoder 等编码平台；用户将模型名设置为 glm-5.4 即可使用。智谱称，这是其首个采用 Loop Transformer 架构的旗舰模型，在 GLM-5 基座模型上让 28 层共享权重循环执行两轮，在参数量不变的情况下获得更深推理，智能水平达到 2-3T 级模型效果。The Decoder 与 MarkTechPost 报道称该模型参数量为 750B。\n\n该模型新增视觉能力，模型列表标注“1M”和“视觉”。智谱称其能力从传统编程延伸至视频、游戏、3D 着色器与 CAD 建模。Coding Plan V2、V3 及团队版用户使用 GLM-5.4 的额度提升至 1.5 倍。\n\n智谱称，API 将在完成安全评估后开放，模型权重计划以负责任的方式开源；The Decoder 称 token 定价尚未公布。MarkTechPost 称目前仅由 Z.ai 托管，自托管硬件要求待权重发布后才会披露。Simon Willison 实测后称，GLM-5.4 目前尚未以开放权重形式提供，且无法通过常规 API 访问，他需订阅 Coding Plan 才能使用。","digestUpdatedAt":"2026-11-24T00:27:51.042Z","reports":[{"id":"v355zd1rteoz5jcwvhklvmeyq","title":"Simon Willison 实测 Z.ai 的 GLM 5.4 及其 Loop Transformer 架构","summary":"Z.ai 发布 GLM 5.4，是其首个采用 Loop Transformer 架构的模型，通过权重共享层多次迭代在不增加参数量的情况下加深网络，暂未开放权重。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-23T23:40:49.000Z","url":"https://simonwillison.net/2026/Nov/23/glm-54/"},{"id":"gkb4y3dxvzr8vhytaeehrelop","title":"Z.ai 发布 GLM-5.4：750B Loop Transformer，28 层循环跑两次","summary":"Z.ai 发布 GLM-5.4，是其首个基于 Loop Transformer 架构的旗舰模型，将 GLM-5 基座的 28 层权重共享层循环运行 2 次，官方称智能水平可比 2T-3T 参数模型。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-23T19:11:40.000Z","url":"https://www.marktechpost.com/2026/11/23/zai-glm-5-4-loop-transformer/"},{"id":"dnri1sadp1o1jmxgpmkx5jv4b","title":"Z.ai 发布 750B 循环架构旗舰模型 GLM-5.4","summary":"Z.ai 发布基于循环 transformer 的 750B 参数旗舰模型 GLM-5.4，让 28 层共享权重运行两次，称性能可比 2 到 3 万亿参数模型。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-23T15:13:03.000Z","url":"https://the-decoder.com/z-ai-follows-openai-into-loop-transformer-territory-with-its-new-750b-flagship-model/"},{"id":"dzf8rz0gf3la7bs8kew4l0zlz","title":"智谱发布 GLM-5.4 循环 Transformer","summary":"推出 GLM-5.4：搭载我们首个循环 Transformer 的通用编程模型。\n\n- 在 GLM-5 基座模型上循环已有层，实现更深层推理\n- 突破传统编程，延伸至视频、游戏、3D 着色器与 CAD 建模\n- 新增视觉能力，强化视觉编程\n\nAPI 将在安全评估后开放。模型权重将负责任地发布。\n\n技术博客：http://z.ai/blog/glm-5.4","sourceName":"X：智谱 Z.ai (@Zai_org)","firstParty":false,"publishedAt":"2026-11-23T10:27:11.000Z","url":"https://x.com/Zai_org/status/2124811995912286352"},{"id":"d4hhqnlmrclsx7d6idtvq95wz","title":"智谱发布GLM-5.4：首个Loop Transformer架构旗舰模型开启泛Coding","summary":"智谱发布旗舰模型GLM-5.4，为第一代采用Loop Transformer架构的模型，让28层共享权重循环执行两轮，在参数量不变下获得更深推理，智能水平达到2-3T级模型效果，并开启泛Coding能力。","sourceName":"公众号：智谱（GLM）","firstParty":false,"publishedAt":"2026-11-23T09:42:11.000Z","url":"https://mp.weixin.qq.com/s/D-IZr-QaT1or_chminK8IQ"},{"id":"dusrrvphsk2lm8qswivm4s0vs","title":"智谱 GLM-5.4 上线 Coding Plan，新增视觉能力","summary":"智谱官方运营人员宣布 GLM-5.4 模型已上线 Coding Plan，用户将模型名设置为 glm-5.4 即可使用。该模型新增视觉能力与更强的泛 Coding 能力，模型列表显示“1M”和“视觉”字样。V2、V3 及团队版用户的 GLM-5.4 使用额度提升至 1.5 倍，模型具体介绍信息暂未公布。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T04:49:30.313Z","url":"https://www.ithome.com/1/030/809.htm"}]},"c5ab5cf5-6316-4ad6-9d74-f0b378a2b064":{"publicId":"c5ab5cf5-6316-4ad6-9d74-f0b378a2b064","title":"OpenAI 提议以困惑度设共同安全上限，微软公布可比数据","status":"active","sourceCount":12,"reportCount":16,"firstReportAt":"2026-11-22T00:00:00.000Z","latestAt":"2026-11-23T18:42:38.000Z","latest":"OpenAI 首席科学家 Jakub Pachocki 公布 GPT 系列困惑度分数并呼吁同行约定共同安全限制","digest":"OpenAI 首席科学家 Jakub Pachocki 发表《Perplexity and Intelligence》，提议把困惑度（交叉熵损失）作为跨模型开发者的共享比较指标，并据此设立共同安全上限：超过门槛的进展须以人类理解 AI 行为的能力为前提。OpenAI 同时公开预训练 log-perplexity 走势图，覆盖 GPT-3.5 到 GPT-6.2 Astra 的 base model，并标注一个 internal model 点位。\n\nCEO Sam Altman 表态支持，称 OpenAI 正在大幅公开预训练进展，希望各方就共同限制达成一致；他还提议前沿模型开发者共同建立评估模型、红线测试安全案例的行业规范，包括共享透明度标准，并以困惑度等测量设定开发者承诺不逾越的共同上限，直到理解与监控 AI 行为的能力达到具体里程碑（如 CoT 监控器的后继技术）。首席研究官 Mark Chen 呼吁前沿实验室披露追踪进展的关键指标，并提出困惑度作为候选标准。\n\n微软 AI CEO Mustafa Suleyman 表示完全支持该倡议，并公布 MAI-2 Base 在 OpenAI 评测集上的 log-perplexity 为 0.819，与 GPT-5.6 Sol base 相当；他称两者使用同一 tokenizer 因而可直接比较，且微软能访问 OpenAI 评测集属于特殊情况。Dan Hendrycks 引用该文及公开曲线估算，自 GPT-4 以来预训练计算效率平均每年提升约 3–5 倍，大部分增益来自最近一年。上述内容目前仍是 OpenAI 方面的提议，尚未成为行业或公司的既定规则。","digestUpdatedAt":"2026-11-23T19:36:06.401Z","reports":[{"id":"crw4tsq5rknyz5r8urr18du0y","title":"OpenAI 首席科学家 Jakub Pachocki 公布 GPT 系列困惑度分数并呼吁同行约定共同安全限制","summary":"OpenAI 首席科学家 Jakub Pachocki 在博客公布 GPT 系列的 log-perplexity 内部分数，希望让困惑度成为行业衡量进展的共同指标。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-23T18:42:38.000Z","url":"https://the-decoder.com/openai-warns-that-upcoming-ai-systems-could-outpace-safety-checks-and-urges-rivals-to-agree-on-shared-limits/"},{"id":"ahiv28657urifplozo1csu3lg","title":"微软 AI 负责人苏莱曼支持 OpenAI 透明度倡议，公布 MAI-2 Base 评测结果","summary":"微软 AI 负责人穆斯塔法·苏莱曼在 X 平台表示完全支持 OpenAI 提高透明度的倡议，认为这是 AI 安全协调方面朝正确方向迈出的一步。微软承诺在双方共同保留的评测集上分享预训练进展，经 OpenAI 许可公布的 MAI-2 Base 对数困惑度为 0.819，与 GPT-5.6 Sol 基础模型处于相近水平，且因使用与 OpenAI 相同的分词器，数字可直接比较。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T01:00:23.127Z","url":"https://www.ithome.com/1/030/745.htm"},{"id":"l2sbkxmzbg1zq5xe2cazob89m","title":"Mustafa Suleyman 支持 OpenAI 透明度倡议，公布 MAI-2 Base 困惑度数据","summary":"Microsoft AI CEO Mustafa Suleyman 表示完全支持 OpenAI 的预训练透明度倡议，并公布 MAI-2 Base 在 OpenAI 评测集上的 log-perplexity 为 0.819，与 GPT-5.6 Sol base 相当，两者使用同一 tokenizer 因而可直接比较。","sourceName":"X：Mustafa Suleyman（Microsoft AI CEO） (@mustafasuleyman)","firstParty":false,"publishedAt":"2026-11-23T00:37:29.000Z","url":"https://x.com/mustafasuleyman/status/2124663594449318173"},{"id":"vfd82yb3feq7ixwb9uw6infzx","title":"OpenAI 首席科学家 Jakub 发文倡议用对数困惑度衡量底层智能进展","summary":"indigo 解读 OpenAI 首席科学家 Jakub 的倡议文「Perplexity and Intelligence」，主张行业用对数困惑度反映预训练阶段涌现的底层智能，以免 RL 阶段失控。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-23T00:26:48.000Z","url":"https://x.com/indigox/status/2124660902092042722"},{"id":"lev71ucng72fc2757tvu5e001","title":"OpenAI 首席科学家 Jakub Pachocki 提议为先进 AI 设共同开发门槛，警告 2027 年或现能力加速","summary":"OpenAI 首席科学家 Jakub Pachocki 发文提议 AI 企业建立行业统一标准，在安全监控能力可靠之前不突破约定的发展门槛，CEO 奥尔特曼公开支持。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-22T22:50:46.817Z","url":"https://www.ithome.com/1/030/720.htm"},{"id":"w6aesnkh72hkkxhr4ptrhddd9","title":"OpenAI 首席科学家 Jakub Pachocki 提议以 perplexity 作为限制 AI 发展速度的度量","summary":"OpenAI 首席科学家 Jakub Pachocki 发文提议以 perplexity 作为衡量 AI 进展的共同基准，用于在企业间建立发展速度的共同限制。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-22T21:14:07.000Z","url":"https://techcrunch.com/2026/11/22/openais-chief-scientist-has-thoughts-on-how-to-limit-ai-development/"},{"id":"w710a5d202zi2gg348cz01fob","title":"OpenAI 首席研究官 Mark Chen 呼吁前沿实验室共享关键指标并公开自家困惑度数据","summary":"OpenAI 首席研究官 Mark Chen 表示各实验室自写安全案例、自设护栏导致 AI 竞赛动态难以摆脱，呼吁前沿实验室披露追踪进展的关键指标，并提出困惑度作为候选标准。","sourceName":"X：Mark Chen（OpenAI 首席研究官，@markchen90）","firstParty":false,"publishedAt":"2026-11-22T19:55:58.000Z","url":"https://x.com/markchen90/status/2124592748099665943"},{"id":"uyaqmati59kykshezwugs41bh","title":"Greg Brockman 解读 OpenAI 基于困惑度的预训练共同安全上限提议","summary":"Greg Brockman 介绍 OpenAI《Perplexity and Intelligence》一文，主张基于困惑度等指标设立开发者承诺不逾越的共同安全上限，并配以明确的退出标准（如 CoT monitors 的后继工具问世）。他认为对齐与监控进展可能不够快，无法支撑预训练的充分加速，目标是形成逐级设限、控制发展节奏的共同框架。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-22T19:15:59.000Z","url":"https://x.com/gdb/status/2124582684840399311"},{"id":"ugbmwlfgci2rzkqvdevqn8a2b","title":"Suleyman 称赞 OpenAI 预训练透明度倡议","summary":"这非常重要。非常感谢 @merettm 和 OAI 为此发声倡导。","sourceName":"X：Mustafa Suleyman（Microsoft AI CEO） (@mustafasuleyman)","firstParty":false,"publishedAt":"2026-11-22T18:43:17.000Z","url":"https://x.com/mustafasuleyman/status/2124574455972364689"},{"id":"dks2nr0fsbmlkolagvqk6w4g7","title":"Dan Hendrycks 估算 GPT-4 以来预训练计算效率每年提升约 3–5 倍","summary":"Dan Hendrycks 引用 OpenAI 发布的《Perplexity and Intelligence》一文及其公开的基座模型困惑度曲线，估算自 GPT-4 以来预训练计算效率平均每年提升约 3–5 倍，即达到相同 loss 所需算力每年缩减至三分之一到五分之一。他指出大部分增益来自最近一年，这可能意味着今年的提升达到约 100 倍以上。","sourceName":"X：Dan Hendrycks (@hendrycks)","firstParty":false,"publishedAt":"2026-11-22T18:31:04.000Z","url":"https://x.com/hendrycks/status/2124571381295984764"},{"id":"u09xn1k898u9moe4eh0mrsq3b","title":"OpenAI 谈困惑度与AI安全标准","summary":"各实验室在白宫协议下同意建立标准和最佳实践，以提升其系统的安全性，我相信围绕困惑度使用的讨论可以进一步推进这些目标。","sourceName":"X：Sam Altman (@sama)","firstParty":false,"publishedAt":"2026-11-22T17:40:44.000Z","url":"https://x.com/sama/status/2124558713646428663"},{"id":"nrzd48iqj8z40nyvlmqhtlp80","title":"OpenAI 发布 Perplexity and Intelligence，公开预训练困惑度进展数据","summary":"OpenAI 发布文章 Perplexity and Intelligence，主张基于困惑度等测量设立共同安全门槛，超过门槛的进展应以对 AI 行为的理解能力为前提，并首次公开预训练进展数据。文中图表展示从 GPT-3.5 到 GPT-6.2 Astra 的 base model log-perplexity 走势，并标注了一个 internal model 点位。Noam Brown 转发称 AI 将影响所有人，包括内部模型在内，所有人都有权知道进展轨迹。","sourceName":"X：Noam Brown (@polynoamial)","firstParty":false,"publishedAt":"2026-11-22T17:26:43.000Z","url":"https://x.com/polynoamial/status/2124555186043818245"},{"id":"kxc2p9z20b5dlbk419t6hbp3d","title":"Sam Altman 提议前沿模型开发者共同建立评估与安全红线测试的行业规范","summary":"Sam Altman 提议各前沿模型开发者共同建立评估模型和红线测试安全案例的行业共同规范，包括共享透明度标准。他还建议基于困惑度等测量设定开发者承诺不逾越的共同上限，直到理解与监控 AI 行为的能力达到具体里程碑（例如 CoT 监控器的后继技术），形成规定开发首道上限及突破前所需条件的行业标准。","sourceName":"X：Sam Altman (@sama)","firstParty":false,"publishedAt":"2026-11-22T17:13:35.000Z","url":"https://x.com/sama/status/2124551883130114403"},{"id":"kbsk3p0n2qaxicnh39x32fvlh","title":"OpenAI 公开预训练进展呼吁共同安全限制","summary":"这是 OpenAI 一段时间以来发布的最重要的内容。\n\n我们正在对预训练进展提供大量透明度，希望我们能作为朋友就共同限制达成一致。我认为这将非常明智，有助于确保安全与可控。","sourceName":"X：Sam Altman (@sama)","firstParty":false,"publishedAt":"2026-11-22T17:12:27.000Z","url":"https://x.com/sama/status/2124551594691932405"},{"id":"lwm6f6xtf8667axqr5snwas7u","title":"OpenAI 首席科学家 Jakub Pachocki 发文主张以 perplexity 设共同安全门槛并公开预训练进展","summary":"OpenAI 首席科学家 Jakub Pachocki 宣布为推动共同安全标准，提高 OpenAI 预训练进展的透明度，并发布文章《Perplexity and Intelligence》。他在文中主张基于 perplexity 等度量设立共同上限，超越门槛的进展应以理解 AI 行为的能力为前提，并附模型 log-perplexity 随时间下降的图表。","sourceName":"X：Jakub Pachocki（OpenAI 首席科学家，@merettm）","firstParty":false,"publishedAt":"2026-11-22T17:03:00.000Z","url":"https://x.com/merettm/status/2124549218995949967"},{"id":"r7kb35fpdwc1m2iqsmd310tdj","title":"OpenAI 提议以困惑度作为行业共享指标并公开内部预训练测量数据","summary":"OpenAI 撰文提议将 perplexity（交叉熵损失）确立为跨模型开发者比较和安全标准的共享指标，并公开其内部预训练测量数据。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-22T00:00:00.000Z","url":"https://openai.com/index/perplexity-and-intelligence"}]},"647b0945-9244-4f55-b509-0f3fa0f6fe51":{"publicId":"647b0945-9244-4f55-b509-0f3fa0f6fe51","title":"Lean 社区确认阿尔波格黎曼猜想证明正确","status":"active","sourceCount":13,"reportCount":20,"firstReportAt":"2026-11-20T15:37:46.650Z","latestAt":"2026-11-23T13:59:36.000Z","latest":"Meta 首席 AI 官 Alexandr Wang：Riemann 突破后，AI 行业还没准备好迎接超智能","digest":"Anthropic 数学家莱文特·阿尔波格 2026 年 11 月 20 日宣称与 Claude 合作证明了黎曼猜想，并称方法可推广至广义黎曼猜想；他没有发表论文，只放出约 1700 万行 Lean 代码。Lean 与 Mathlib 社区随后发表声明确认该证明正确：数十人独立运行得到相同结果，验证程序被设计为不会接受有缺陷的证明。\n\n此前 The Verge 报道称该证明尚未经独立验证，Anthropic 未就阿尔波格的宣布置评。菲尔兹奖得主詹姆斯·梅纳德表示相信证明正确，依据是它已通过 Lean 形式化验证并经独立核实；但他同时称，证明需被理解才可能获得认可。\n\n关于功劳归属仍有分歧：阿尔波格称 Claude 在最后阶段远超自己并提出关键步骤，Gary Marcus 则强调这不是 AI 独立完成，而是数学家数月深度协作的成果。陶哲轩此前曾表示现有 AI 无法攻克该问题。","digestUpdatedAt":"2026-11-23T14:31:03.380Z","reports":[{"id":"cmp47ofzxdxbuy4c7peji2ncz","title":"Meta 首席 AI 官 Alexandr Wang：Riemann 突破后，AI 行业还没准备好迎接超智能","summary":"Meta 首席 AI 官 Alexandr Wang 称，AI 模型在 Riemann 猜想上给出证明草图，说明原始智能已不再是瓶颈，超智能近在眼前。他认为当前模型只缺领域知识和实际基础设施，很快就能在几乎所有领域超越人类，包括自动化 AI 研究本身。他警告行业把超智能视为必然、只关注安全，却忽视了确保 AI 增强而非控制社会这一更大议题。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-23T13:59:36.000Z","url":"https://the-decoder.com/metas-alexandr-wang-warns-the-ai-industry-isnt-ready-for-whats-coming-after-riemann-breakthrough/"},{"id":"se6kyzulklfw7rruyo86r3c46","title":"Gary Marcus 评 Levent Alpöge 借助 Claude 证明黎曼猜想：不是 AI 独立完成，也难以泛化","summary":"Gary Marcus 分析 Levent Alpöge 在 Claude 协助下疑似证明黎曼猜想一事，指出并非 AI 独立完成，而是这位数学家数月深度协作的成果。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-22T18:37:02.000Z","url":"https://garymarcus.substack.com/p/levent-alpoge-has-solved-the-riemann"},{"id":"ikpixx0j7414se1f6lww2csek","title":"Lean 与 Mathlib 社区确认 Levent Alpöge 黎曼猜想证明正确","summary":"Lean 与 Mathlib 社区发表声明，确认斯坦福数学家 Levent Alpöge 的黎曼猜想证明正确。Alpöge 于 2026 年 11 月 20 日以 1700 万行 Lean 代码发布该证明，数十人独立运行得到相同结果，且验证程序被设计为可证明不会接受有缺陷的证明。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-22T11:08:31.000Z","url":"https://the-decoder.com/lean-and-mathlib-community-officially-confirms-levent-alpoges-proof-of-the-riemann-hypothesis-is-correct/"},{"id":"p9h5xzsooms0foxeakoivy7qt","title":"菲尔兹奖得主梅纳德谈 Claude 合作证明黎曼猜想：相信证明正确，但需被理解才可能获认可","summary":"2022 年菲尔兹奖得主、牛津大学数学教授詹姆斯·梅纳德（James Maynard）在采访中表示，他认为 Anthropic 数学家莱文特·阿尔珀格（Levent Alpöge）与 Claude 合作完成的黎曼猜想证明是正确的，依据是该证明已通过 Lean 库形式化验证并经独立核实，且阿尔珀格过往有可靠记录。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-22T09:35:58.183Z","url":"https://www.ithome.com/1/030/677.htm"},{"id":"sur1rc2t4erze02ozroefugff","title":"Anthropic 数学家称与 Claude 可能证明黎曼猜想，同日人类数学家也给出证明","summary":"Anthropic 数学家 Levent Alpöge 称他与 Claude 可能证明了黎曼猜想，其证明长达 1740 万行 Lean。同日斯坦福数学家 Ravi Vakil 也发布了 Alessandro Masullo 对该猜想的证明，强调\"全由人类完成、无 AI 参与\"。Alpöge 的证明尚未被阅读核验，Masullo 的证明正由第三方检查并翻译为 Lean。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-11-22T04:59:51.000Z","url":"https://www.exponentialview.co/p/ev-611"},{"id":"dkuj083l2zugx0h11b2yx9nkm","title":"黎曼猜想证明该归功于谁","summary":"以后黎曼猜想的证明，大家谈论更多的会是 Levent Alpöge 还是 Claude？","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-22T00:51:47.000Z","url":"https://x.com/SaitoWu/status/2124304802477982189"},{"id":"h0ti6sx4gk0mij86ymdl4szv3","title":"Grok 谈黎曼猜想的证明意义","summary":"对黎曼证明（目前为止）有用性的简单解释是：它消除了其他依赖于此的数学定理的条件性。\n\n当然，这也是超级智能取得的又一件令人震撼的成就……\n\nhttps://x.com/i/grok/share/bGVnYWN5_2b134790-72b8-47d6-b182-afb9b775bd6a","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-21T18:49:42.000Z","url":"https://x.com/elonmusk/status/2124213680422387741"},{"id":"tje8i8y21ttk7jjmqet5bpxuq","title":"Anthropic 数学家称与 Claude 完成黎曼猜想证明，斯坦福数小时后发布纯人类竞争草稿","summary":"Anthropic 数学家 Levent Alpöge 周五宣布与 Claude 合作得到黎曼猜想及广义黎曼猜想的证明，证明以 Lean 语言分 14 个数据包发布，打印将超 25 万页。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-21T11:19:49.000Z","url":"https://the-decoder.com/hours-after-anthropic-claims-a-claude-proof-of-the-riemann-hypothesis-stanford-releases-an-all-human-competing-draft/"},{"id":"gpib9pwvar2m6yp9lsd5111ri","title":"Grok 谈黎曼猜想即将被解决","summary":"即使黎曼猜想最终尚未被完全解决，也很快就会了\n https://x.com/i/grok/share/bGVnYWN5_883c4778-e70d-4d39-b95d-c807591b80b0","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-21T07:46:48.000Z","url":"https://x.com/elonmusk/status/2124046857659650295"},{"id":"h9u457be00wxrafjnehfbd9xl","title":"Rohan Paul 对照陶哲轩上月言论转发 Anthropic 数学家声称与 Claude 证明黎曼猜想的消息","summary":"Rohan Paul 引用转发称，Anthropic 数学家 Alpöge 表示他与 Claude 合作证明了 167 年未解的黎曼猜想，用时约六周，并把整个论证形式化为可机器检验的代码。作者同时附上陶哲轩上月访谈视频，陶哲轩当时表示现有 AI 无法攻克该问题，可能要到 2050 年前后由人类与 AI 结合才能取得进一步进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-21T07:20:09.000Z","url":"https://x.com/rohanpaul_ai/status/2124040149830926708"},{"id":"m3euloe30yztem02vuvbps0hs","title":"Anthropic 数学家 Levent Alpöge 声称与 Claude 合作证明黎曼猜想，同日现独立人类证明","summary":"Latent Space 汇总报道，Anthropic 数学家 Levent Alpöge 声称在与 Claude 合作下证明黎曼猜想，方法还覆盖广义黎曼猜想（GRH），仅发布 Lean 代码，散文版约 250,000 页；Elliot Glazer 确认形式化陈述为 GRH，并将 Lean 出错概率估计远低于 1%。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-21T05:02:13.000Z","url":"https://latent.space/p/ainews-riemann-hypothesis-proved-twice-independently/"},{"id":"iwtvrbj2ir0p8tr7ioqedaxwo","title":"Rohan Paul 引述 Thiel 2024 年预言回应 Claude 协助证明黎曼假设的说法","summary":"作者引用 @rohanpaul_ai 转述的消息称，Anthropic 数学 Alpöge 与 Claude 经约六周工作并形式化为机器可检验代码，宣称证明了 167 年未解的黎曼假设；作者补充 Peter Thiel 2024 年的说法，即 3 到 5 年内 AI 将能解开全美数学奥赛题，对数学研究者冲击更大。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-21T00:18:26.000Z","url":"https://x.com/rohanpaul_ai/status/2123934024628596896"},{"id":"gt179blsp9ok1jlaq3dxf521f","title":"Anthropic 数学家 Alpöge 称与 Claude 合作证明黎曼假设","summary":"Anthropic 数学家 Alpöge 宣布他与 Claude 合作证明了黎曼假设，称 Claude 提出关键步骤令他惊叹，工作历时约六周，并将整个论证形式化为机器可检验的代码。作者引用 Brian Greene 的说法，该证明约 25 万页，目前没有人类能够完全理解。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T22:40:25.000Z","url":"https://x.com/rohanpaul_ai/status/2123909356483940512"},{"id":"hsbh8rxnbqfw9pzhqq5rw4ihe","title":"Anthropic 数学家 Levent Alpöge 公布黎曼猜想的 Lean 可编译证明，Stanford 博士后同期发布纯人工证明","summary":"Anthropic 数学家 Levent Alpöge 宣布找到黎曼猜想的 Lean 可编译证明，该猜想提出于 1859 年，是千禧年大奖难题之一。他在文章中描述了与 Claude 协作完成论证的经历，数学界正通过 Zulip 讨论审查这一形式化结果。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T19:32:08.000Z","url":"https://techcrunch.com/2026/11/20/ai-claimed-a-solution-to-the-167-year-old-riemann-hypothesis-and-a-human-did-too/"},{"id":"jfvlkn07rmizh1b1tc1li2gjx","title":"Anthropic 数学家 Alpöge 称与 Claude 合作证明了黎曼猜想","summary":"Rohan Paul 转述：Anthropic 数学家 Alpöge 自称与 Claude 合作证明了有 167 年历史的黎曼猜想，方法是把两个作用于简化“玩具”版本的想法引向真问题，由 Claude 接手他未掌握的高级领域并提出关键步骤，全程约六周，并把论证形式化为机器可检验的代码。Alpöge 称 Claude 的一个想法会让同行数学家“从椅子上摔下来”，并表示该方法还可推广到广义黎曼猜想。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T17:38:08.000Z","url":"https://x.com/rohanpaul_ai/status/2123833283863789602"},{"id":"vu6fw8wmrs3xcln4u9gwzf1f4","title":"Anthropic数学家Alpöge宣布与Claude共同证明黎曼猜想，放出1737万行Lean代码","summary":"Anthropic数学家Levent Alpöge在其个人网站宣布与Claude共同给出黎曼猜想证明，未发论文，只放出175187个Lean文件、共1737万行代码。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-20T16:54:55.000Z","url":"https://mp.weixin.qq.com/s/8Zi3nfwddzFy6cZsK2_KxA"},{"id":"zd0je1l7flwl146g4067qfk36","title":"Anthropic 数学家 Levent Alpöge 称借助 Claude 证明了黎曼假设","summary":"Anthropic 数学家 Levent Alpöge 在个人网站声称与 Claude 合作证明了黎曼假设，并表示方法可推广至广义黎曼假设，证明以 Lean 形式化。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T16:34:13.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1010051/anthropic-riemann-hypothesis-millennium-prize-problem"},{"id":"ho0o6xob2p10mu52ghd7vyl81","title":"数学家 Levent Alpöge 自称与 Claude 合作发现黎曼猜想证明","summary":"Simon Willison 转述数学家 Levent Alpöge 的自述：他称与 Claude 合作发现了黎曼猜想（Riemann Hypothesis）的证明，且方法可推广到广义与扩展黎曼猜想，并已无假设地形式化论证。他形容过程中 Claude 在最后阶段远超自己，并将这一经历视为科学领域更大变革的开端，原文链接 alpo.ge/remark.pdf。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-20T16:30:48.000Z","url":"https://simonwillison.net/2026/Nov/20/levent-alpoge/"},{"id":"dwqvqargdgum4wu55gtbk6hxx","title":"François Chollet 转发 Anthropic 数学家称用 AI 证明黎曼猜想的报道","summary":"François Chollet 转发 Scientific American 的报道并评论 What a time to be alive。报道称一位 Anthropic 数学家声称用该公司 AI 解决了黎曼猜想，这一数学界最著名的未解难题，并附上原文链接。","sourceName":"X：Francois Chollet (@fchollet)","firstParty":false,"publishedAt":"2026-11-20T15:42:30.000Z","url":"https://x.com/fchollet/status/2123804181941424178"},{"id":"px9zx0q62ir3bw68722mfdqui","title":"Anthropic 数学家阿尔波格宣称与 Claude 合作完成黎曼猜想证明","summary":"Anthropic 数学家莱文特·阿尔波格当地时间 20 日在个人网站宣称，与 AI 模型 Claude 合作找到黎曼猜想的证明，并编写为 Lean 代码以待逐步验证。他称证明还覆盖范围更广的广义黎曼猜想，若获确认，大量以此为前提的数学结论将随之得到证实，论文原文见 https://alpo.ge/remark.pdf。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-20T15:37:46.650Z","url":"https://www.ithome.com/1/030/278.htm"}]},"51379310-d375-40d8-88e1-a8112bca2c10":{"publicId":"51379310-d375-40d8-88e1-a8112bca2c10","title":"亚马逊75亿美元收购Decart大部分业务","status":"active","sourceCount":3,"reportCount":4,"firstReportAt":"2026-11-22T00:10:14.000Z","latestAt":"2026-11-24T00:13:49.970Z","latest":"亚马逊收购 Decart 的 AI 优化技术，报道称交易约 75 亿美元","digest":"亚马逊已同意以约75亿美元收购以色列AI初创公司Decart的大部分业务，包括其Decart Optimization Stack（DOS）优化技术、创始团队及AI研究与工程团队。亚马逊已宣布这一收购并邀请Decart联合创始人及员工加入，但未披露财务条款；75亿美元金额来自彭博社援引知情人士的说法。\n\n此前《金融时报》报道称双方处于深入谈判阶段，交易最早可能在本周初达成，但仍存在破裂风险。DOS是一款软件引擎，可提升AI系统运行速度，并支持在英伟达、谷歌、亚马逊等厂商的AI芯片间切换；Decart已获得亚马逊Trainium3芯片的早期访问权限，亚马逊称该芯片运行其实时视频模型的速度比GPU快4倍、成本减半。\n\n75亿美元对价接近Decart最新一轮40亿美元估值的两倍，具体交割安排尚未披露。","digestUpdatedAt":"2026-11-24T00:45:00.554Z","reports":[{"id":"s0b5vkivqye5r3a4y3dy5soc8","title":"亚马逊收购 Decart 的 AI 优化技术，报道称交易约 75 亿美元","summary":"亚马逊宣布收购 Decart 公司的 AI 优化技术，并邀请其联合创始人和员工加入，彭博社援引知情人士称交易金额约 75 亿美元，亚马逊未披露财务条款。Decart 成立于 2023 年，主打产品为 Decart Optimization Stack（DOS）软件引擎，可帮助企业提升 AI 系统运行速度并在英伟达、谷歌、亚马逊等厂商的 AI 芯片间切换。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-24T00:13:49.970Z","url":"https://www.ithome.com/1/031/262.htm"},{"id":"l9peziox0fxdgvldq3uydhvxg","title":"Amazon 以 75 亿美元收购 Decart 优化技术，筹备对外销售 Trainium 芯片","summary":"Amazon 已同意以 75 亿美元收购以色列初创公司 Decart 的大部分业务，包括其 Decart Optimization Stack（DOS）优化技术、创始团队及 AI 研究与工程团队。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T17:14:23.000Z","url":"https://techcrunch.com/2026/11/23/amazon-snaps-up-decarts-ai-optimization-tech-for-7-5b-as-it-prepares-to-sell-trainium-chips/"},{"id":"fk0e4fc7ny52yueq4mmxsifm6","title":"消息称亚马逊接近以 75 亿美元收购 AI 初创公司 Decart","summary":"《金融时报》报道称，Amazon 已就收购 AI 初创公司 Decart 展开深入谈判，交易价值约 75 亿美元，最早可能在本周初达成协议，但仍存在破裂风险。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T03:35:46.710Z","url":"https://www.ithome.com/1/030/797.htm"},{"id":"eg97pyuem4incr7vpqsklw36v","title":"Amazon 接近以约 7.5B 美元收购 AI 创业公司 Decart","summary":"Amazon 接近以约 $7.5B 收购 AI 创业公司 Decart，几乎是其最新 $4B 估值的两倍。据报道，Decart 的优化能从 Amazon 处理器中获得更高 token 效率；Decart 获得了 Trainium3 早期访问权限，Amazon 称该芯片运行其实时视频模型的速度比 GPU 快 4 倍、成本减半。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-22T00:10:14.000Z","url":"https://x.com/rohanpaul_ai/status/2124294348712092061"}]},"9474636b-5271-405b-91d7-b469bdf1aa8f":{"publicId":"9474636b-5271-405b-91d7-b469bdf1aa8f","title":"Anthropic 发布 Claude Ship 测试版，自动审查并批准 PR","status":"active","sourceCount":11,"reportCount":15,"firstReportAt":"2026-11-23T00:00:00.000Z","latestAt":"2026-11-24T00:02:39.000Z","latest":"Anthropic 发布 Claude Ship，覆盖 GitHub PR 审查到修复","digest":"Anthropic 发布 Claude Ship 测试版，让 Claude 审查 pull request、推送修复，并按团队写进仓库的策略文件决定能否批准合并。产品由已正式可用的 Code Review 和处于 beta 的 PR Steward、Claude Approvals 两个智能体组成：PR Steward 处理失败的 CI 检查、合并冲突和审查反馈并留言说明改动；Claude Approvals 依据仓库中的 .claude/approvals.yml 策略批准常规改动，可配置通过人数和路径规则。\n\nClaude Ship 面向 Claude Team 和 Enterprise 客户、支持 GitHub 仓库，不适用于启用零数据保留、HIPAA 配置或客户自管密钥的组织。符合条件的 Claude Enterprise 组织可申领至少 1 万美元额度，须在申领后 30 天内使用，申领截止 2027 年 1 月 15 日。Team 或 Enterprise 管理员可按 GitHub repo 为整个仓库开启，团队 PR 无需 /ship 即可自动运行；Claude Code 的 /ship 命令正在 CLI 和桌面应用中逐步开放，任何人可使用。费用按 token 计费，随 PR 数量、审查深度和 PR Steward 投入的工作量变化。合并仍由用户的权限和分支规则决定。\n\nAnthropic 建议团队先以观察模式运行审批功能，在不实际执行审批的情况下观察其判断结果，也可先在单个仓库启用并设置每月支出上限。Boris Cherny 称，这些功能成倍提升了他的开发速度，无需等待 code review 或盯着 PR，结果也更好。Claude Devs 提示 Claude Ship 使用 AI，可能遗漏 bug 或安全问题。","digestUpdatedAt":"2026-11-24T00:48:51.106Z","reports":[{"id":"h0cco60oiwe37arv7x3pdupj9","title":"Anthropic 发布 Claude Ship，覆盖 GitHub PR 审查到修复","summary":"Anthropic 发布 Claude Ship，包含 Code Review、PR Steward 和 Claude Approvals 三个 Agent，可将 GitHub PR 从审查推进到批准；Code Review 已正式可用，其余两个处于公测。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-24T00:02:39.000Z","url":"https://www.marktechpost.com/2026/11/23/anthropic-claude-ship-pull-request-agents/"},{"id":"lxyhdhyjwd5qp8w3jo3pfvg3l","title":"Anthropic 推出 Claude Ship 测试版：AI 自动完成代码审查、修复与批准","summary":"Anthropic 推出 Claude Ship Beta 测试版，一套 AI 智能体工具，可自动完成代码审查、修复和批准。其包含 Code Review、PR Steward 和 Claude Approvals 三项功能，Code Review 已正式开放，后两项处于 Beta 阶段。Anthropic 建议团队先以观察模式运行审批功能，并可在单个仓库启用、设置每月支出上限。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T23:49:00.083Z","url":"https://www.ithome.com/1/031/257.htm"},{"id":"cf7exc2q4r0gpagip2rcepyy2","title":"Anthropic 推出 Claude Ship beta，自动审查并按策略审批 PR","summary":"Anthropic 的 ClaudeDevs 发布 Claude Ship（beta），Claude 可审查 pull request、修复问题，并按团队策略允许的范围自动批准。作者补充称它覆盖从 review 到自动审批的 PR 全生命周期，帮助承接各种编码工具带来的 PR 吞吐量。","sourceName":"X：Noah Zweben（@noahzweben）","firstParty":false,"publishedAt":"2026-11-23T22:25:45.000Z","url":"https://x.com/noahzweben/status/2124992828996768156"},{"id":"mlop8hozs26imcfjayymd6vn9","title":"Anthropic 发布 Claude Ship，让 AI Agent 审查、修复并审批代码变更","summary":"Anthropic 发布 Claude Ship，一组用于自动化代码审查、修复和审批的 AI Agent。其中 Code Review 已正式可用，PR Steward 和 Claude Approvals 处于 beta，后者可按团队以自然语言写入仓库的审批策略自动批准变更。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T22:05:50.000Z","url":"https://techcrunch.com/2026/11/23/anthropic-launches-claude-ship-letting-ai-agents-review-fix-and-approve-code-changes/"},{"id":"mo9ri8nex517xyijhdw83ywnb","title":"Claude Ship (beta) 发布：审查 PR、修复问题并按团队策略批准","summary":"Anthropic 官方 @ClaudeDevs 宣布推出 Claude Ship (beta)：Claude 可以审查你的 pull request、参与修复，并批准团队策略允许的合并，目标是让代码能按你写出来的速度交付。作者 Lydiahallie 作为 Claude Code 团队成员转发并配上 /ship 🚢。","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-23T20:48:44.000Z","url":"https://x.com/lydiahallie/status/2124968415316361462"},{"id":"pa7y6lb03wza7cwwikew64sqr","title":"Anthropic 推出 Claude Ship 公测：可审查 PR、修复问题并按策略审批","summary":"Anthropic 推出 Claude Ship（beta），Claude 可以审查 pull request、参与修复，并批准团队策略允许的 PR。目标是帮助开发者以接近书写代码的速度交付代码。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-23T20:24:59.000Z","url":"https://x.com/adocomplete/status/2124962436029841746"},{"id":"ape2l2bmhd99j8ql1myg113yb","title":"Claude Code 推出 /ship 与 Claude Ship 功能，Team 和 Enterprise 可按 repo 开通","summary":"Boris Cherny 介绍 Claude Ship 功能：任何人可使用 /ship，Team 或 Enterprise 计划的管理员可按 GitHub repo 开通 Claude Ship。他建议先从一个 repo 开始，在信任建立前让 Approvals 以 observe 模式运行，并附介绍文章链接 claude.com/resources/articles/introducing-claude-ship。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-23T20:21:13.000Z","url":"https://x.com/bcherny/status/2124961488691740941"},{"id":"da9x2u8i3q7gwi3tbyynwlo7k","title":"Boris Cherny 介绍 Claude Code 的 Code Review、PR Steward 与 Claude Approvals 功能","summary":"Boris Cherny 介绍 Claude Code 新增的代码审查与 PR 工作流功能，称其成倍提升自己的开发速度，无需等待 code review 或盯着 PR，结果也更好。具体包括查找 bug 的 Code Review、处理修复和失败检查的 PR Steward，以及按团队策略批准的 Claude Approvals，后两者处于 beta 阶段。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-23T20:21:13.000Z","url":"https://x.com/bcherny/status/2124961487454384442"},{"id":"bogrl7sijta9kbxqrgfy7hz10","title":"Anthropic 推出 Claude Ship beta：可审查 PR、修复代码并按团队策略批准合并","summary":"Boris Cherny 宣布面向 Team 和 Enterprise 推出 Claude Ship（beta），用于弥补写代码与发布 PR 之间的落差。Claude Ship 可以审查 pull request、处理修复，并批准团队策略允许的合并，目标是让发布代码的速度跟上写代码的速度。作者称自己每天都在使用。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-23T20:21:12.000Z","url":"https://x.com/bcherny/status/2124961485801836573"},{"id":"oom14bdotou4ycx1qqm0kwway","title":"Anthropic Claude Code 团队推出 Claude Ship，自动处理 PR 审查、修复与审批","summary":"Claude Code 团队推出 Claude Ship（beta），可将 PR 走完审查、修复和基于团队策略的审批决策。","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-23T20:16:08.000Z","url":"https://x.com/addyosmani/status/2124960211287101656"},{"id":"abjvysdchmlsi68fbinr7orat","title":"Claude Ship 支持 Team 与 Enterprise 管理员按仓库启用自动审批","summary":"Claude Ship 在 Team 和 Enterprise 计划中支持管理员为整个仓库开启，团队 PR 无需 /ship 即可自动运行。审批策略以 .claude/approvals.yml 文件形式存放在仓库中，可配置通过人数、路径规则和 Claude 审核通过后的覆盖判定，作用类似更智能的 CODEOWNERS 文件。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-23T20:13:05.000Z","url":"https://x.com/ClaudeDevs/status/2124959440772137337"},{"id":"b8e3upoinqevs0u08u79ckn3o","title":"Claude Code 推出 /ship 命令，自动开 PR 并跟进审查与修复","summary":"Anthropic 的 Claude Code 推出 /ship 命令，正在 CLI 和桌面应用中逐步开放，可让 Claude 打开 PR、审查改动并处理反馈和失败的检查。图片展示 Review、Fix（PR Steward，BETA）、Approve（Claude Approvals，BETA）三个环节的流程，最终在团队策略下达到 Ready to merge，并提示 Claude Ship 使用 AI、可能遗漏 bug 或安全问题。合并仍由用户的权限和分支规则决定。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-23T20:13:04.000Z","url":"https://x.com/ClaudeDevs/status/2124959438175981965"},{"id":"gt4d8yrshukcau05h4zsfrmpc","title":"Anthropic 推出 Claude Ship 测试版，可审查 PR 并按团队策略批准","summary":"Anthropic 推出 Claude Ship（beta），Claude 可审查 pull request、着手修复问题，并批准符合团队策略的部分。目标是帮助开发者以写代码的速度更快发布。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-23T20:13:04.000Z","url":"https://x.com/ClaudeDevs/status/2124959436640858475"},{"id":"sy80jk76lkvjtf63d6v5xncpi","title":"Anthropic 推出 Claude Ship，可自动审查并合入 PR","summary":"Anthropic 发布 Claude Ship，让 Claude 能审查、修复并批准 pull request。其中 PR Steward 和 Claude Approvals 两个智能体以 beta 形式上线，前者处理失败的 CI 检查、合并冲突和审查反馈并留言说明改动，后者在组织政策允许时可批准常规改动。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T20:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1040134/anthropic-claude-ship-ai-pull-requests"},{"id":"t7jlbaldqf2zcliuva1sofoks","title":"Anthropic 推出 Claude Ship 测试版，自动完成 PR 审查、修复与审批","summary":"Anthropic 发布 Claude Ship 测试版，由 Code Review（已正式可用）、PR Steward 和 Claude Approvals 两个 beta 智能体组成，可审查 PR、推送修复并按团队写进仓库的策略文件决定能否合并。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-11-23T00:00:00.000Z","url":"https://claude.com/blog/introducing-claude-ship"}]},"0cf0f02a-0464-43db-b253-ed1878937b74":{"publicId":"0cf0f02a-0464-43db-b253-ed1878937b74","title":"Thinking Machines 开源循环模型 Inkling 2 Mini","status":"active","sourceCount":15,"reportCount":25,"firstReportAt":"2026-11-19T16:00:00.000Z","latestAt":"2026-11-23T21:39:25.000Z","latest":"Inkling 2 Mini 进入 Agent Arena Index 开源模型第 18 名","digest":"Thinking Machines Lab 发布开源权重模型 Inkling 2 Mini，采用循环 Transformer 架构：24 层中中间 12 层对每个 token 循环运行三次，首尾各六层只运行一次。模型总参数 26.4B，以 Apache 2.0 许可在 Hugging Face 发布完整权重及可变循环研究版本，并上线 Tinker 供推理和微调。\n\n官方称其可在 32GB 以上内存的 Mac 本地运行，也可在 NVIDIA DGX Spark 上运行；vLLM 提供 Day-0 支持，Ollama 预发布版可一条命令运行，Unsloth 称 1-bit 量化仅需 9GB 内存，并称其 GGUF 本地推理提速约 1.9 倍、在 RTX Pro 6000 上达 125 tokens/s 且无精度损失。评测方面，Artificial Analysis 智能指数得 20 分，ARC Prize 公布 ARC-AGI-2 得分 49.3%、每任务 $0.14，ARC-AGI-1 得分 84.5%、每任务 $0.06；Arena 称其进入 Agent Arena Index，在开源模型中排第 18（996 分）、美国开放权重模型中排第 3。\n\n循环架构引发可监控性担忧，Thinking Machines 称研究发现多次循环下 no-CoT 能力上升、思维链变短但仍可读，可监测性没有明显下降，并同步开源可变循环研究模型供外部实验；NDIF 已托管该模型及变体，提供白盒访问。各来源对激活参数表述不一，有 3B、3.4B、5.4B 三种说法。","digestUpdatedAt":"2026-11-23T22:06:57.858Z","reports":[{"id":"sgpgukk3dh0ass7hk9wz8c1pl","title":"Inkling 2 Mini 进入 Agent Arena Index 开源模型第 18 名","summary":"Arena 官宣 Thinking Machines 的 Inkling 2 Mini 进入 Agent Arena Index，在开源模型中排第 18（996 分），美国开放权重模型中排第 3。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-23T21:39:25.000Z","url":"https://x.com/arena/status/2124981167279546382"},{"id":"vqyyhkzvlzd95mthgqs9bf4qe","title":"Unsloth 让 Inkling 2 Mini 本地推理提速约 1.9 倍","summary":"Unsloth 宣布 Inkling 2 Mini GGUF 本地推理提速约 1.9 倍，在 RTX Pro 6000 上可达 125 tokens/s 且无精度损失。所有量化版本已更新以兼容 llama.cpp 及使用它的引擎，并修复了 Q8_0 KV cache 导致内存占用高于 F16 的问题；用户可通过 Unsloth Desktop 运行，GGUF 和指南见 Hugging Face 与 unsloth.ai。","sourceName":"X：Unsloth (@UnslothAI)","firstParty":false,"publishedAt":"2026-11-23T16:10:21.000Z","url":"https://x.com/UnslothAI/status/2124898356770263382"},{"id":"edmf4gjl80s2neuc4w0vjgsbp","title":"Thinking Machines Lab 发布循环 Transformer 模型 Inkling 2 Mini","summary":"Thinking Machines Lab（TML）于当地时间本月 20 日发布循环 Transformer 架构模型 Inkling 2 Mini。模型共 24 层，分四个 6 层模块，中间两个模块运行 3 次，并对专家节点从 384 个剪枝至 128 个；整体为 26.4B-A3.4B，考虑循环后每个词元激活权重 5.4B。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T06:55:25.030Z","url":"https://www.ithome.com/1/030/907.htm"},{"id":"kjnjqumqxr3miozl533n0arvh","title":"Thinky Machines 的 Inkling 2 Mini 登顶 HF 趋势榜","summary":"来自 @thinkymachines 的 Inkling 2 Mini 在 HF 上排名趋势第一（而来自 @UnslothAI 的 gguf 排名第二）。冲！","sourceName":"X：Clément Delangue（Hugging Face CEO） (@ClementDelangue)","firstParty":false,"publishedAt":"2026-11-21T18:31:39.000Z","url":"https://x.com/ClementDelangue/status/2124209139337331158"},{"id":"lgvi0yp86fz5e1bcj6trfdmn2","title":"Thinking Machines 发布开源权重模型 Inkling 2 Mini：26.4B 循环 MoE 可在 32GB Mac 上运行","summary":"Thinking Machines 发布开源权重循环 Transformer 模型 Inkling 2 Mini，总参数 26.4B、每 token 激活 3.4B，以 Apache 2.0 协议上架 Hugging Face。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-21T12:13:50.000Z","url":"https://www.marktechpost.com/2026/11/21/thinking-machines-inkling-2-mini-looped-transformer/"},{"id":"zixjeyn76xptget44y2x0v6jo","title":"Thinking Machines 发布开源循环 Transformer 模型 Inkling 2 Mini","summary":"Thinking Machines 发布开源模型 Inkling 2 Mini，一种循环 Transformer：24 层中的 12 层对每个 token 连跑三次，可在不生成更多文本的情况下延长内部推理，用更少 token 找到答案。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-21T10:33:02.000Z","url":"https://the-decoder.com/new-open-model-inkling-2-mini-thinks-in-loops-to-solve-problems-with-fewer-words-and-still-runs-on-a-laptop/"},{"id":"g6zp7jjfe2qwlvxvy6kqeobbm","title":"Inkling 2 Mini 机上离线造飞行模拟器","summary":"昨天团队申请批准“飞去任何地方”，为 Inkling 2 Mini 做飞机 bench：","sourceName":"X：Mira Murati（@miramurati）","firstParty":false,"publishedAt":"2026-11-21T00:47:56.000Z","url":"https://x.com/miramurati/status/2123941448479559687"},{"id":"msggmz9hhf3y7axytsidyx2nn","title":"Inkling 2 Mini 上架 Ollama，一条命令即可本地运行","summary":"Thinking Machines 转发 Ollama 的消息，Inkling 2 Mini 已随 Ollama 0.40.17 预发布版上架，用 ollama run inkling-2-mini 即可完全本地运行。该模型 5.4B 激活参数，token 会在中间层循环三次以加深推理，32GB 以上内存的 Mac 即可运行，面向编码、computer use、视觉推理和金融等智能体任务。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-21T00:14:07.000Z","url":"https://x.com/thinkymachines/status/2123932938492649575"},{"id":"f3e6qg9gdbj3ydgkpp6j2e7v6","title":"NDIF 上线 Thinking Machines 的 Inkling 2 Mini 白盒访问","summary":"Thinking Machines 宣布 NDIF 现已托管 Inkling 2 Mini 及其 variable-loop 变体，提供白盒访问，用户无需自有算力即可运行模型并干预其内部。NDIF 同时提供跨 loop 读取、patch 和引导模型激活的指南。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-21T00:08:41.000Z","url":"https://x.com/thinkymachines/status/2123931570436518245"},{"id":"rxpjyf0p90v7j0fkryq48oels","title":"Inkling 2 Mini 上架 Arena，可测试 26B 参数小模型","summary":"Arena 宣布 Thinking Machines 的 Inkling 2 Mini 上架 Agent Arena，这是一个 26B 参数的 looped transformer 小模型，官方分数即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-20T22:58:57.000Z","url":"https://x.com/arena/status/2123914021883756728"},{"id":"zvoeth3rwv2yj6b14ep4qfqf6","title":"Thinky Machines 登 ARC Prize 排行榜","summary":"@thinkymachines - 排行榜：https://arcprize.org/leaderboard\n- 复现公开结果：https://github.com/arcprize/arc-agi-benchmarking\n- 测试政策：https://arcprize.org/policy\n- 完整结果：https://arcprize.org/results/thinky-inkling-2-mini","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-20T21:04:37.000Z","url":"https://x.com/arcprize/status/2123885245426770229"},{"id":"rxj2v60ofmyzndb6xmv8fxsau","title":"ARC Prize 公布 Inkling 2 Mini 的 ARC-AGI (Verified) 成绩","summary":"ARC Prize 公布 thinkymachines 的 Inkling 2 Mini 在 ARC-AGI (Verified) 上的成绩：ARC-AGI-2 得分 49.3%、每任务 $0.14，ARC-AGI-1 得分 84.5%、每任务 $0.06。与 Inkling 2 Small 相比，在 ARC-AGI-2 上每任务成本低 47%，但得分低 32 个百分点。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-20T21:03:50.000Z","url":"https://x.com/arcprize/status/2123885049091440920"},{"id":"rwfbyx3cu15nqxzdbr5919hnt","title":"Thinking Machines 发布开源权重模型 Inkling 2 Mini，Artificial Analysis 智能指数得分 20","summary":"Thinking Machines 发布 Inkling 2 Mini，在 Artificial Analysis 智能指数得 20 分，处于智能与活跃参数的 Pareto 前沿。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-20T20:35:18.000Z","url":"https://x.com/ArtificialAnlys/status/2123877871316087012"},{"id":"h3c7hoefv74f6q02h3l5rfemm","title":"Unsloth 发布 Inkling 2 Mini 本地运行指南，26.4B MoE 模型可在 16GB 内存运行","summary":"Unsloth 提供了 Thinking Machines 新发布的 Inkling 2 Mini 的本地运行支持，这是一款 Apache 2.0 的 26.4B（激活 5.4B）MoE 模型，采用 Looped Transformer 架构和 1M 上下文。该模型 DeepSWE v1.1 得分 48.2%、SWE-Bench Pro v2 (Hard) 得分 77.9%，为其尺寸中最高；GGUF 已上传至 Hugging Face，1-bit 量化仅需 9GB 内存，4-bit 需 17-18GB，可通过 Unsloth 和 llama.cpp 运行。","sourceName":"X：Unsloth (@UnslothAI)","firstParty":false,"publishedAt":"2026-11-20T20:18:33.000Z","url":"https://x.com/UnslothAI/status/2123873656069877899"},{"id":"gj2mmwqy7kojuxu6j3eyy1pbn","title":"Thinking Machines 开源 Inkling 2 Mini（Apache 2.0）","summary":"Thinking Machines 发布 Inkling 2 Mini，以 Apache 2.0 协议开源，模型已上架 Hugging Face。作者称其达到开源 Agent 模型的 Pareto 前沿；对比表显示该模型 5.4B/26.4B 激活/总参数，在 AA Index、Vals Index、FrontierCode、DeepSWE 等基准上领先 Gemma 4 31B、Muse Glimmer 等对比模型。","sourceName":"X：Clément Delangue（Hugging Face CEO） (@ClementDelangue)","firstParty":false,"publishedAt":"2026-11-20T20:17:20.000Z","url":"https://x.com/ClementDelangue/status/2123873347393970488"},{"id":"q6orirqf2j4ccyt2oq8356s8c","title":"Thinking Machines 发布 Inkling 2 Mini：26B 参数 looped transformer 可在笔记本运行","summary":"Mira Murati 发布 Inkling 2 Mini，一个仅 26B 参数的 looped transformer，小到可在笔记本上运行，在 AA Index 得分 20.1，此前 Inkling 2 Small 有 594B 参数被认为过大。她称循环机制让模型多思考少输出，该规模下思维过程仍可监控，团队还同步开源了一个 variable-loop 研究模型供进一步研究。","sourceName":"X：Mira Murati（@miramurati）","firstParty":false,"publishedAt":"2026-11-20T20:14:06.000Z","url":"https://x.com/miramurati/status/2123872534970208421"},{"id":"fbixrtyecgwczbxheseom58ik","title":"Inkling 2 Mini 登陆 Ollama 与 DGX Spark","summary":"Inkling 2 Mini 可通过 @ollama 在 32GB 内存的 Mac 上运行，也可在 NVIDIA 的 DGX Spark 上运行。它已上线 Tinker，用于推理和微调，并已入驻 Tinker Playground。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:35.000Z","url":"https://x.com/thinkymachines/status/2123871647371501591"},{"id":"gar8sck1ea3i6zjs6vp0lzgjh","title":"Thinking Machines 发布 26B 参数的 Inkling 2 Mini","summary":"Thinking Machines 回应部分用户认为 Inkling 2 Small 的 594B 参数过大的反馈，发布 looped transformer 架构的 Inkling 2 Mini，仅 26B 参数。模型小到可在笔记本上运行，AA Index 得分 20.1，面向智能体任务，详情见 thinkingmachines.ai/news/inkling-2-mini/。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:34.000Z","url":"https://x.com/thinkymachines/status/2123871643797995872"},{"id":"s5n9o0z0bdu4kn5ip2rtrt4lc","title":"Inkling 2 Mini 循环 Transformer 可监控性研究","summary":"Inkling 2 Mini 是一个 24 层的循环 Transformer。中间 12 层循环三次；首尾各六层只运行一次。\n\n循环让模型在少写的同时进行更多推理，这引发了对可监控性的担忧。我们在发布过程中对此进行了研究。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:34.000Z","url":"https://x.com/thinkymachines/status/2123871645039464643"},{"id":"yewn8su7mvqeun52a9yovp1g3","title":"Thinking Machines 发布可变循环研究模型，发现 no-CoT 能力随循环次数提升","summary":"Thinking Machines 发现多次循环下 no-CoT 能力随循环次数上升，链式思维变短但仍可读，可监测性没有明显下降。团队同时发布一个可变循环研究模型，供其他人运行自己的实验。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:34.000Z","url":"https://x.com/thinkymachines/status/2123871646176166358"},{"id":"y7nk77dxae51qwi826gpmvbho","title":"Thinking Machines Lab 发布可跑在笔记本上的开源权重模型 Inkling 2 Mini","summary":"Thinking Machines Lab 发布开源权重模型 Inkling 2 Mini，采用循环 Transformer 架构，将中间 12 层每 token 运行三次，总参数 26.4B、激活 3.4B，内存占用约 20GB，可在 32GB 内存以上的 Mac 本地运行。","sourceName":"Thinking Machines Lab：News（网页）","firstParty":true,"publishedAt":"2026-11-20T07:00:00.000Z","url":"https://thinkingmachines.ai/news/inkling-2-mini/"},{"id":"uy9a6qm6p671jbogn3c1r4b98","title":"Hugging Face 联合 Thinking Machines Lab 发布本地多模态模型 Inkling 2 Mini","summary":"Hugging Face 与 Thinking Machines Lab 合作发布面向本地部署的多模态 MoE 模型 Inkling 2 Mini，总参数约 26B、每 token 激活 3B。","sourceName":"Hugging Face 官方团队博客","firstParty":true,"publishedAt":"2026-11-20T00:00:00.775Z","url":"https://huggingface.co/blog/inkling2mini"},{"id":"ve55b8roz3vc4cq7t5ohtsixt","title":"vLLM Day-0 支持 Thinking Machines 循环模型 Inkling 2 Mini","summary":"Thinking Machines 发布 Inkling 2 Mini，vLLM 在 Blackwell、Hopper 和 DGX Spark 上提供 Day-0 支持。","sourceName":"vLLM 官方博客（RSS）","firstParty":true,"publishedAt":"2026-11-20T00:00:00.000Z","url":"https://vllm.ai/blog/2026-11-20-inkling2-mini"},{"id":"j84gvc6i39lzdh4f4t1p8w5ju","title":"Thinking Machines 发布开源权重循环架构模型 Inkling 2 Mini","summary":"Thinking Machines 发布开源权重循环 Transformer 模型 Inkling 2 Mini，Apache 2.0 许可，26B 总参数、5.4B 激活参数的 MoE 架构，支持文本和图像输入、1M token 上下文窗口，可在 MacBook 或 DGX Spark 上运行。","sourceName":"Artificial Analysis 完整文章（网页）","firstParty":true,"publishedAt":"2026-11-19T16:00:00.000Z","url":"https://artificialanalysis.ai/articles/inkling-2-mini"},{"id":"tfvuikboev6dm8u2rck1dx8fb","title":"Goodfire 解析 Thinking Machines 开源模型 Inkling 2 Mini 的内部机制","summary":"Goodfire Research 发布对 Thinking Machines 开源权重模型 Inkling 2 Mini 的可解释性研究，该模型有 24 层，采用 attention residuals 和中间块循环三次的架构。","sourceName":"Goodfire Research（网页）","firstParty":true,"publishedAt":"2026-11-19T16:00:00.000Z","url":"https://www.goodfire.com/research/interpreting-inkling-2-mini"}]},"e04baccb-6e1d-4072-8167-8272457c90d1":{"publicId":"e04baccb-6e1d-4072-8167-8272457c90d1","title":"特朗普公开支持黄仁勋回归英伟达","status":"active","sourceCount":2,"reportCount":3,"firstReportAt":"2026-11-20T22:31:43.000Z","latestAt":"2026-11-23T15:04:01.000Z","latest":"Trump 力挺黄仁勋回归 Nvidia，称美国政府无其不当行为的证据","digest":"","digestUpdatedAt":null,"reports":[{"id":"uop2ab4998l6dxugsgtg7w7rn","title":"Trump 力挺黄仁勋回归 Nvidia，称美国政府无其不当行为的证据","summary":"Trump 在 Truth Social 上表态支持 Nvidia 董事会复职黄仁勋为 CEO 兼总裁，称美国政府没有理由认为其回归构成国家安全风险。他称司法部长 Todd Blanche 已确认政府没有黄仁勋违法行为的证据，但 Blanche 本人尚未正式声明。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T15:04:01.000Z","url":"https://techcrunch.com/2026/11/23/trump-endorses-jensen-huangs-return-to-nvidia-says-us-has-no-evidence-of-wrongdoing/"},{"id":"ieyb9ul94lhhe75vqo5mxlny5","title":"特朗普发帖呼吁 Nvidia 董事会重新雇用黄仁勋","summary":"特朗普在 Truth Social 发帖称，希望 Nvidia 董事会重新雇用黄仁勋，并称这对公司和美国都是最好的事情。Rohan Paul 转发了这条帖文截图，帖子显示 812 次 ReTruths 和 3.18k 点赞。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-23T03:36:58.000Z","url":"https://x.com/rohanpaul_ai/status/2124708759255843188"},{"id":"k1hyvjqvrfajnxnn85pkgtu1l","title":"Trump 在白宫称黄仁勋是全球最聪明的人之一并希望他回归","summary":"Trump 今日在白宫评价 NVIDIA 的黄仁勋是「世界上真正最聪明的人之一」，并称「我很乐意看到他回归」，同时希望黄仁勋「做出大道歉后回来」。他还提到 Blackwell 先进复杂到无法复制。完整视频可在 C-SPAN YouTube 频道观看。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T22:31:43.000Z","url":"https://x.com/rohanpaul_ai/status/2123907168210751878"}]},"2d0a9c1a-2a0a-41b6-a7ef-776ef03a783b":{"publicId":"2d0a9c1a-2a0a-41b6-a7ef-776ef03a783b","title":"200万诱饵请求测出AI服务链数据外泄","status":"active","sourceCount":5,"reportCount":6,"firstReportAt":"2026-11-20T20:59:08.000Z","latestAt":"2026-11-24T01:23:02.687Z","latest":"因提示词和密钥外泄，OpenRouter 清退 Together AI、Phala、Novita 三家服务商","digest":"安全公司 Dragos 首席研究官 HD Moore 在 2026 年 7 月至 11 月间，经 OpenRouter 等 AI 路由向多家服务商发送近 200 万条带可追踪诱饵和假凭证的请求，发现提示词被窃、转售商外传数据、隐私设置未被执行。部分凭证被外部人员用于尝试访问受控测试系统和 AWS 测试账户，表明提示词已流出预期处理范围；部分标记“零数据保留”（ZDR）的请求，其私密网址数日后仍被抓取。\n\nOpenRouter 回应称未发现自身被入侵，问题出在部分推理提供商数据泄露或数据政策未被执行。OpenRouter 已清退 Together AI、Phala 和 Novita 三家服务商，撤销 125 个端点的 ZDR 资格并通知可能受影响的客户；被移出的端点须提供适当保证并通过验证，才能恢复 ZDR 资格。\n\nMoore 建议敏感业务本地部署或直接选择可信服务商；Dragos 还建议企业控制 AI 请求的路由方式、检查隐私设置并植入自有的金丝雀令牌。","digestUpdatedAt":"2026-11-24T01:47:37.582Z","reports":[{"id":"vchj846k6pi9hwzpbfo8hohk6","title":"因提示词和密钥外泄，OpenRouter 清退 Together AI、Phala、Novita 三家服务商","summary":"OpenRouter 清退 Together AI、Phala 和 Novita 三家服务商，撤销 125 个服务端点的零数据保留资格，并通知可能受影响的客户。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-24T01:23:02.687Z","url":"https://www.ithome.com/1/031/282.htm"},{"id":"kbrosmbvldj069ds87zid0wlp","title":"Dragos研究揭示低价AI推理服务商窃取密钥并窥探用户请求","summary":"Dragos安全研究人员在2026年7月至11月期间向AI服务商发送约200万条含假凭证的请求，发现至少三家服务商遭入侵，攻击者窃取数百个AWS密钥并在数小时内试用、搜索S3存储，部分攻击者还使用了AI攻击工具ARTEX。研究还发现，部分市场转售商无需利用漏洞即可读取客户请求，仅需以最低价上架模型并开启日志记录。隐私设置如“零数据保留”（ZDR）常被忽视。OpenRouter随后从平台移除三家服务商并撤销125个端点的ZDR批准，同时邮件通知受影响用户。受影响服务商包括Novita、Phala和Together，已发布初步安全报告。Dragos建议企业控制AI请求路由方式、检查隐私设置并植入自有的金丝雀令牌。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-22T12:07:56.000Z","url":"https://the-decoder.com/security-researchers-show-how-cheap-ai-inference-providers-steal-keys-and-snoop-on-users/"},{"id":"yj1o6pemhdr7th9xt779xzt0m","title":"OpenRouter 回应推理提供商数据处理问题：下架 3 家并收紧 ZDR 资格","summary":"安全研究人员发现 OpenRouter 平台上部分推理提供商存在数据处理问题，但未波及 OpenRouter 本身。OpenRouter 已下架 3 家提供商、将许多端点移出 ZDR 资格范围并通知受影响客户，还计划把研究人员的测试纳入持续检查，完整更新发布在其博客。","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-22T01:32:38.000Z","url":"https://x.com/OpenRouter/status/2124315081899200715"},{"id":"dvvqir3buzkemt3nqplef9omx","title":"OpenRouter 因推理提供商数据处理事件下架三家提供商并移除 125 个 ZDR 端点","summary":"OpenRouter 针对安全研究人员报告的部分推理提供商数据泄露或数据政策未被执行问题发布公告，称未发现 OpenRouter 本身被入侵。","sourceName":"OpenRouter：Announcements（RSS）","firstParty":true,"publishedAt":"2026-11-22T00:00:00.000Z","url":"https://openrouter.ai/blog/announcements/data-processing-incidents-on-inference-providers/"},{"id":"n1sb4nib4897yds1wpi0dgwky","title":"近 200 万条诱饵请求揭示 AI 服务链隐私泄露：零数据保留也失效","summary":"安全公司 Dragos 首席研究官 HD Moore 向多家 AI 服务商发送近 200 万条带可追踪诱饵的请求，发现提示词被窃、转售商外传数据及隐私设置未被执行等问题。至少三家服务商出现遭入侵迹象，被盗诱饵密钥被用于数万次云服务接口调用；部分标记零数据保留的请求其私密网址数日后仍被抓取，Moore 建议敏感业务可本地部署或直接选择可信服务商。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-21T02:03:24.083Z","url":"https://www.ithome.com/1/030/322.htm"},{"id":"agm7klro03kcu9weuix1bt4su","title":"研究者向 AI 供应链埋入 200 万个金丝雀，揭露敏感数据泄露","summary":"研究者在经过 OpenRouter 等 AI 路由的请求中埋入 200 万个金丝雀链接，测试敏感信息是否会沿 AI 服务链泄露，结果显示这些数据像筛子一样大量外泄。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T20:59:08.000Z","url":"https://arstechnica.com/security/2026/11/a-leaky-ai-supply-chain-is-exposing-secret-user-data-at-an-alarming-rate/"}]},"b8056250-7988-49be-a8a0-4c9425a3b63c":{"publicId":"b8056250-7988-49be-a8a0-4c9425a3b63c","title":"美国商务部将新加坡Megaspeed列入实体清单","status":"active","sourceCount":5,"reportCount":8,"firstReportAt":"2026-11-11T02:40:09.000Z","latestAt":"2026-11-23T21:48:25.000Z","latest":"美国商务部将新加坡芯片采购商Megaspeed列入实体清单","digest":"美国商务部已将新加坡芯片采购商 Megaspeed 列入实体清单，禁止美国供应商在无许可证情况下向其及海外关联公司出售半导体等受控技术。此前数月，国务院、财政部、国防部等机构已同意列名，但负责发布规则的商务部一直搁置；财政部长贝森特曾就此质问商务部长卢特尼克，白宫官员也被曝在权衡是否撤换卢特尼克。\n\n背景是这家英伟达前主要客户被指将受限芯片转运至中国客户在东南亚的数据中心。美国商务部 2024 年启动出口调查，英伟达于 2025 年 6 月停止供货并将其列入禁售名单；商务部和司法部随后发布联合声明称刑事调查由司法部牵头，未指英伟达违规。由于英伟达已断供，此次列名主要封堵其他美国供应商的服务器销售及对关联公司销售等间接渠道。Megaspeed 否认存在不当行为。","digestUpdatedAt":"2026-11-23T22:45:04.057Z","reports":[{"id":"zto0pspydy8330r0bvwqb6j5z","title":"ChinaTalk播客：Nvidia董事会恢复黄仁勋CEO职务，Megaspeed被列入实体清单","summary":"ChinaTalk主持Jordan Schneider邀请Chris McGuire和Peter Harrell录制播客，讨论Nvidia董事会全票恢复黄仁勋CEO职务（距其辞职仅十一天），以及美国商务部同日将Megaspeed列入实体清单。嘉宾围绕出口管制与制裁实务，分析了董事会决策背景、Megaspeed实体清单未附加外国直接产品规则（FDPR）等细节，并探讨了后续监管走向。","sourceName":"ChinaTalk（RSS）","firstParty":false,"publishedAt":"2026-11-24T01:41:25.000Z","url":"https://www.chinatalk.media/p/jensen-returns"},{"id":"mgtrekf99glsi26aguyvgdtwe","title":"美国商务部将新加坡芯片采购商Megaspeed列入实体清单","summary":"据Semafor报道，美国商务部已将新加坡芯片采购商Megaspeed列入实体清单，禁止美国供应商在无许可证情况下向其及其海外关联公司出售半导体等受控技术。Megaspeed曾是英伟达主要客户之一，美国商务部于2024年启动出口调查，英伟达于2025年6月停止向其供货。美国财政部长贝森特表示，财政部、国防部、国务院及贸易官员已支持该列名数月。由于英伟达已断供，此次列名主要封堵其他美国供应商的服务器销售及对关联公司销售等间接渠道。该公司否认存在不当行为。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-23T21:48:25.000Z","url":"https://x.com/rohanpaul_ai/status/2124983432854036813"},{"id":"p4xkctditdd1tntt466jm8r0a","title":"Megaspeed 或将被列入美国商务部实体清单","summary":"据 Semafor 援引匿名消息人士报道，新加坡云与 AI 基础设施公司 Megaspeed 可能被美国商务部列入实体清单，美国公司未经特殊许可不得与其交易，此举旨在阻止其获得美国制造的半导体。美国商务部上周还宣布对该公司启动刑事调查，美国和新加坡有关部门正在调查该公司是否违反出口限制。该公司否认存在不当行为。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-23T21:25:42.000Z","url":"https://techcrunch.com/2026/11/23/megaspeed-the-company-at-the-center-of-the-jensen-huang-scandal-appears-headed-for-a-u-s-blacklist/"},{"id":"abxhv94f3gcq1qb9mzdf7yma3","title":"黄仁勋相关传闻核查：美商务部与司法部就Megaspeed发联合声明，未认定违规芯片销售","summary":"围绕英伟达前高管黄仁勋及AI芯片转运传闻，美国商务部与司法部就Megaspeed发布联合声明，未认定存在违规芯片销售，也未将该公司列入实体清单；英伟达此前已主动切断对Megaspeed的供应。相关声明未提及间谍行为，新加坡内政部亦表示未就间谍问题调查该公司负责人。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-18T23:41:28.000Z","url":"https://x.com/thexpin/status/2123199944903581803"},{"id":"b5ebzlz5fzfbmfyx7b4y0w5wk","title":"美国商务部和司法部就 Megaspeed 调查发布联合声明","summary":"美国商务部和司法部发布联合声明，通报对新加坡公司 Megaspeed 的调查进展，称此举是为澄清公开报道中的不准确信息。声明未指 Nvidia 违规，只说 Nvidia 配合提供记录，并于 2025 年 6 月把 Megaspeed 列入禁售名单；同月 BIS 会同新加坡执法人员做了现场最终用途核查并约谈 CEO Alice Huang，刑事调查已由司法部牵头。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-17T05:08:52.000Z","url":"https://x.com/indigox/status/2122557559404106089"},{"id":"pprxwktijyn97bwpgi8dldomp","title":"Reuters：白宫考虑撤换商务部长 Lutnick，Nvidia 客户 Megaspeed 事件波及商务部","summary":"作者引述 Reuters 报道称，白宫官员正权衡撤换商务部长 Howard Lutnick，因 Nvidia 风波波及商务部。正文提到 Lutnick 五月收到机密备忘录，警告黄仁勋与一名涉情报疑云的人士有牵连，但其部门仍未将对方公司 Megaspeed 列入实体清单，该公司已购买超 $4.8B 的 Nvidia AI 芯片。引述的 Axios 报道称财政部长 Scott Bessent 曾就此质问 Lutnick，国务院等多个机构数月前已同意列名，但负责发布规则的商务部一直搁置。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T20:10:36.000Z","url":"https://x.com/rohanpaul_ai/status/2120972552151699634"},{"id":"o2ymtxon6dtjpt3em2pdkw184","title":"美财政部长 Bessent 就 Nvidia 客户 Megaspeed 未被列入黑名单质问商务部长 Lutnick","summary":"据 axios 报道，美国财政部长 Scott Bessent 就 Nvidia 客户 Megaspeed 未被列入黑名单质问商务部长 Howard Lutnick。这家新加坡公司购买了超过 40 亿美元的先进 Nvidia 硬件，用于服务中国客户在东南亚的数据中心。国务院等多个机构数月前已同意将该 firm 列入实体清单，但负责发布规则的商务部一直搁置。图片显示特朗普周四第三次授权打击涉嫌将 Nvidia AI 芯片转售到中国的公司，并在批准前咨询了 Elon Musk。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T23:53:10.000Z","url":"https://x.com/rohanpaul_ai/status/2120666174837207527"},{"id":"yzjhilf6f2s4exh150c4paypo","title":"FT 报道称美国商务部搁置将 Megaspeed 列入出口黑名单","summary":"据 FT 报道，尽管国务院、财政部、能源部和五角大楼等 4 家机构推动将涉嫌转运受限 Nvidia 芯片的 Megaspeed 列入出口黑名单，但主管列入工作的美国商务部已搁置新增名单 2 个月，该公司至今未上 entity list。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T02:40:09.000Z","url":"https://x.com/rohanpaul_ai/status/2120345806855348459"}]}}};
